class Program {
    static class Meter {
        private int units;
        private static int created;
        Meter(int units) { this.units = units; created++; }
        void add(int extra) { units += extra; }
        int units() { return units; }
        static int created() { return created; }
    }
    public static void main(String[] args) {
        Meter first = new Meter(10);
        Meter second = new Meter(20);
        Meter alias = first;
        alias.add(3);
        System.out.println(first.units() + " " + second.units()
                + " " + Meter.created());
    }
}
